    match = re.fullmatch(r"\\(.*)", "\\" + tail)
    assert match is not None
    return match

for tail, expected in simple_escapes.items():
    assert escape(match_escape(tail)) == expected

assert escape(match_escape("x00")) == "\x00"
assert escape(match_escape("x41")) == "A"
assert escape(match_escape("0")) == "\0"
assert escape(match_escape("101")) == "A"
assert escape(match_escape("377")) == "\xff"

for tail in ("x", "xG", "x1G", "", "8", "999"):
    try:
        escape(match_escape(tail))
    except ValueError:
        pass
    else:
        raise AssertionError("ValueError not raised for %r" % tail)

